CREATE OR REPLACE FUNCTION public.validate_voucher_cart(_code text, _cart jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.vouchers%ROWTYPE;
  item jsonb;
  applicable numeric := 0;
  discount numeric := 0;
  uses_by_user integer := 0;
  _uid uuid := auth.uid();
  matches boolean;
  itype text;
  iamount numeric;
  iref text;
BEGIN
  IF _code IS NULL OR length(trim(_code)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bitte gib einen Code ein.');
  END IF;

  SELECT * INTO v FROM public.vouchers WHERE lower(code) = lower(trim(_code)) LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'Code ungültig.'); END IF;
  IF NOT v.is_active THEN RETURN jsonb_build_object('ok', false, 'error', 'Code ist nicht aktiv.'); END IF;
  IF v.valid_from IS NOT NULL AND now() < v.valid_from THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code ist noch nicht gültig.');
  END IF;
  IF v.valid_until IS NOT NULL AND now() > v.valid_until THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code ist abgelaufen.');
  END IF;
  IF v.is_single_use AND v.times_used >= 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code wurde bereits eingelöst.');
  END IF;
  IF v.max_total_uses IS NOT NULL AND v.times_used >= v.max_total_uses THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code wurde bereits maximal oft eingelöst.');
  END IF;
  IF _uid IS NOT NULL AND v.max_uses_per_customer IS NOT NULL THEN
    SELECT count(*) INTO uses_by_user FROM public.voucher_redemptions
      WHERE voucher_id = v.id AND user_id = _uid;
    IF uses_by_user >= v.max_uses_per_customer THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Du hast diesen Code bereits maximal oft genutzt.');
    END IF;
  END IF;

  IF _cart IS NULL OR jsonb_typeof(_cart) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Warenkorb leer.');
  END IF;

  FOR item IN SELECT * FROM jsonb_array_elements(_cart) LOOP
    itype := item->>'type';
    iamount := COALESCE((item->>'amount')::numeric, 0);
    iref := item->>'ref_id';
    matches := false;
    IF 'all' = ANY(v.applies_to) THEN
      matches := true;
    ELSE
      IF itype = 'product' AND 'shop_products' = ANY(v.applies_to) THEN
        IF array_length(v.product_ids, 1) IS NULL THEN matches := true;
        ELSIF iref IS NOT NULL AND iref::uuid = ANY(v.product_ids) THEN matches := true;
        END IF;
      ELSIF itype = 'course' AND 'courses' = ANY(v.applies_to) THEN
        IF array_length(v.course_type_ids, 1) IS NULL THEN matches := true;
        ELSIF iref IS NOT NULL AND iref::uuid = ANY(v.course_type_ids) THEN matches := true;
        END IF;
      ELSIF itype = 'card' AND 'class_cards' = ANY(v.applies_to) THEN
        IF array_length(v.class_card_types, 1) IS NULL THEN matches := true;
        ELSIF iref IS NOT NULL AND iref = ANY(v.class_card_types) THEN matches := true;
        END IF;
      ELSIF itype = 'video_course' AND 'video_courses' = ANY(v.applies_to) THEN
        IF array_length(v.video_course_ids, 1) IS NULL THEN matches := true;
        ELSIF iref IS NOT NULL AND iref::uuid = ANY(v.video_course_ids) THEN matches := true;
        END IF;
      END IF;
    END IF;
    IF matches THEN applicable := applicable + iamount; END IF;
  END LOOP;

  IF applicable <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code gilt nicht für die Artikel in deinem Warenkorb.');
  END IF;

  IF v.discount_amount_fixed IS NOT NULL AND v.discount_amount_fixed > 0 THEN
    discount := LEAST(v.discount_amount_fixed, applicable);
  ELSE
    discount := round(applicable * v.discount_percent / 100.0, 2);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'voucher_id', v.id,
    'code', v.code,
    'discount_percent', v.discount_percent,
    'discount_amount_fixed', v.discount_amount_fixed,
    'applicable_amount', applicable,
    'discount_amount', discount
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_booking_sensitive_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Service-Role / serverseitige Aufrufe (Edge Functions) haben keine auth.uid() – hier durchlassen.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  IF public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'staff') THEN
    RETURN NEW;
  END IF;
  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.amount_paid IS DISTINCT FROM OLD.amount_paid
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.refunded IS DISTINCT FROM OLD.refunded
     OR NEW.voucher_id IS DISTINCT FROM OLD.voucher_id
     OR NEW.payment_id IS DISTINCT FROM OLD.payment_id THEN
    RAISE EXCEPTION 'Not allowed to modify protected booking fields';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_voucher(_code text, _cart_total numeric DEFAULT 0, _product_ids uuid[] DEFAULT '{}'::uuid[], _course_type_ids uuid[] DEFAULT '{}'::uuid[], _card_types text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.vouchers%ROWTYPE;
  applicable_amount numeric := 0;
  discount numeric := 0;
  uses_by_user integer := 0;
  _uid uuid := auth.uid();
BEGIN
  IF _code IS NULL OR length(trim(_code)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bitte gib einen Code ein.');
  END IF;

  SELECT * INTO v FROM public.vouchers WHERE lower(code) = lower(trim(_code)) LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code ungültig.');
  END IF;

  IF NOT v.is_active THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code ist nicht aktiv.');
  END IF;

  IF v.valid_from IS NOT NULL AND now() < v.valid_from THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code ist noch nicht gültig.');
  END IF;
  IF v.valid_until IS NOT NULL AND now() > v.valid_until THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code ist abgelaufen.');
  END IF;

  IF v.is_single_use AND v.times_used >= 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code wurde bereits eingelöst.');
  END IF;

  IF v.max_total_uses IS NOT NULL AND v.times_used >= v.max_total_uses THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code wurde bereits maximal oft eingelöst.');
  END IF;

  IF _uid IS NOT NULL AND v.max_uses_per_customer IS NOT NULL THEN
    SELECT count(*) INTO uses_by_user FROM public.voucher_redemptions
      WHERE voucher_id = v.id AND user_id = _uid;
    IF uses_by_user >= v.max_uses_per_customer THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Du hast diesen Code bereits maximal oft genutzt.');
    END IF;
  END IF;

  -- Determine applicable amount based on scope
  IF 'all' = ANY(v.applies_to) THEN
    applicable_amount := COALESCE(_cart_total, 0);
  ELSE
    applicable_amount := 0;
    IF 'shop_products' = ANY(v.applies_to) THEN
      -- Caller is responsible for passing only applicable totals; if any matching product_ids supplied, allow full
      IF array_length(_product_ids, 1) IS NOT NULL THEN
        IF array_length(v.product_ids, 1) IS NULL THEN
          applicable_amount := applicable_amount + COALESCE(_cart_total, 0);
        ELSIF EXISTS (SELECT 1 FROM unnest(_product_ids) p WHERE p = ANY(v.product_ids)) THEN
          applicable_amount := applicable_amount + COALESCE(_cart_total, 0);
        END IF;
      END IF;
    END IF;
    IF 'courses' = ANY(v.applies_to) AND array_length(_course_type_ids, 1) IS NOT NULL THEN
      IF array_length(v.course_type_ids, 1) IS NULL
         OR EXISTS (SELECT 1 FROM unnest(_course_type_ids) c WHERE c = ANY(v.course_type_ids)) THEN
        applicable_amount := applicable_amount + COALESCE(_cart_total, 0);
      END IF;
    END IF;
    IF 'class_cards' = ANY(v.applies_to) AND array_length(_card_types, 1) IS NOT NULL THEN
      IF array_length(v.class_card_types, 1) IS NULL
         OR EXISTS (SELECT 1 FROM unnest(_card_types) c WHERE c = ANY(v.class_card_types)) THEN
        applicable_amount := applicable_amount + COALESCE(_cart_total, 0);
      END IF;
    END IF;
  END IF;

  IF applicable_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Code gilt nicht für die Artikel in deinem Warenkorb.');
  END IF;

  discount := round(applicable_amount * v.discount_percent / 100.0, 2);

  RETURN jsonb_build_object(
    'ok', true,
    'voucher_id', v.id,
    'code', v.code,
    'discount_percent', v.discount_percent,
    'applicable_amount', applicable_amount,
    'discount_amount', discount
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_order_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.order_number IS NULL THEN
    NEW.order_number := public.next_number('order');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_course_no()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.course_no IS NULL THEN
    NEW.course_no := nextval('public.courses_course_no_seq');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_order_paid(_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  updated_cards int := 0;
  updated_bookings int := 0;
  updated_access int := 0;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'staff')) THEN
    RAISE EXCEPTION 'Nicht berechtigt';
  END IF;

  UPDATE public.orders
    SET status = 'paid', paid_at = COALESCE(paid_at, now())
    WHERE id = _order_id;

  WITH u AS (
    UPDATE public.class_cards SET status = 'active'
    WHERE order_id = _order_id AND status = 'pending_payment'
    RETURNING 1
  ) SELECT count(*) INTO updated_cards FROM u;

  WITH u AS (
    UPDATE public.bookings SET status = 'confirmed'
    WHERE order_id = _order_id AND status = 'pending_payment'
    RETURNING 1
  ) SELECT count(*) INTO updated_bookings FROM u;

  WITH u AS (
    UPDATE public.video_course_access SET status = 'active'
    WHERE order_id = _order_id AND status = 'pending_payment'
    RETURNING 1
  ) SELECT count(*) INTO updated_access FROM u;

  RETURN jsonb_build_object(
    'ok', true,
    'cards_activated', updated_cards,
    'bookings_confirmed', updated_bookings,
    'video_access_activated', updated_access
  );
END;
$function$
